var cur=+(tr.querySelector('input[name$="[cost]"]').value||0),l=h.last,t='<div style="color:var(--n)"><b>Last:</b> '+money(l.cost)+' · '+H(dshort(l.date))+(l.supplier?' · '+H(l.supplier):'')+'</div>';
